const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;padding:8px;overflow:hidden;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer;margin:0}\n.card button:focus-visible,.card input:focus-visible,.card textarea:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.btn{flex:none;height:28px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);white-space:nowrap;font-size:12.5px}\n.btn.sm{height:24px;padding:0 8px;font-size:11.5px}\n.btn.pri,.btn.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.inp{width:100%;height:30px;min-width:0;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.inp::placeholder{color:var(--muted);opacity:.85}\n.inp.ta{height:auto;min-height:60px;padding:6px 8px;resize:vertical;line-height:1.4}\n.tag{flex:none;max-width:100%;padding:0 6px;border:1px solid var(--line);border-radius:6px;background:var(--soft);color:var(--muted);font-size:10.5px;line-height:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.err{flex:none;padding:4px 8px;border:1px solid var(--line);border-radius:8px;background:var(--soft);font-size:12px}\n\n/* list page */\n.top{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.ttl{flex:none;font-weight:700;font-size:14px;white-space:nowrap}\n.cnt{font-weight:400;font-size:11.5px;color:var(--muted)}\n.top .search{flex:1;min-width:0;height:28px}\n.body{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.chips{flex:none;display:flex;flex-direction:row;gap:4px;overflow-x:auto;overflow-y:hidden;padding-bottom:3px;scrollbar-width:thin}\n.chips.off{display:none}\n.chip{flex:none;max-width:140px;height:24px;display:flex;align-items:center;gap:4px;padding:0 9px;border:1px solid var(--line);border-radius:999px;background:transparent;color:var(--ink);font-size:11.5px;text-align:left}\n.chip .nm{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.chip .n{flex:none;opacity:.7;font-size:10.5px}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.chip.sm{height:22px;font-size:11px;padding:0 8px}\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:5px;scrollbar-width:thin}\n.row{flex:none;width:100%;min-width:0;display:flex;flex-direction:column;gap:1px;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);text-align:left}\n.r1,.r2{display:flex;align-items:center;gap:6px;min-width:0}\n.r1 .nm{flex:1;min-width:0;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.r2{font-size:11.5px}\n.r2 .ad{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--accent);font-weight:600}\n.r2 .ad.none{color:var(--muted);font-weight:400}\n.r2 .dt{flex:none;color:var(--muted);font-size:10.5px;white-space:nowrap}\n.row .tp,.row .loc,.row .chg,.row .hit{display:none;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:var(--muted)}\n.row .loc{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:10.5px}\n.row .hit{display:block;color:var(--ink);background:var(--soft);border-radius:5px;padding:0 4px;margin-top:2px}\n.empty{margin:auto;max-width:300px;display:flex;flex-direction:column;align-items:center;gap:6px;padding:8px;text-align:center;color:var(--muted);font-size:12px}\n.empty .et{font-weight:600;color:var(--ink);font-size:13px}\n.empty .long{display:none}\n\n/* detail page */\n.dtop{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.dname{flex:1;min-width:0;font-weight:700;font-size:14px;line-height:1.25;word-break:break-all;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.vers{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:6px;scrollbar-width:thin}\n.dmeta{flex:none;display:flex;flex-wrap:wrap;gap:4px}\n.tag.warn{color:var(--ink)}\n.ver{flex:none;display:flex;flex-direction:column;gap:3px;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.ver.cur{border-left:4px solid var(--accent);background:var(--soft)}\n.vh{display:flex;align-items:center;flex-wrap:wrap;gap:4px 8px;min-width:0}\n.vl{font-size:14px}\n.vd{color:var(--muted);font-size:11.5px}\n.badge{margin-left:auto;padding:0 7px;border-radius:999px;background:var(--accent);color:var(--on-accent);font-size:10.5px;line-height:18px;white-space:nowrap}\n.kv{display:flex;gap:6px;min-width:0;font-size:12px}\n.kv .k{flex:none;width:2.4em;color:var(--muted)}\n.kv .v{flex:1;min-width:0;overflow-wrap:anywhere;word-break:break-word}\n.mono{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11.5px}\n.acts{display:flex;flex-wrap:wrap;align-items:center;gap:5px;margin-top:3px}\n.ask{flex:1 1 100%;font-size:12px}\n.foot{flex:none;display:flex;gap:6px}\n.foot .btn{flex:1;height:32px}\n\n/* form page */\n.fbody{flex:1;min-height:0;min-width:0;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));align-content:start;gap:8px;padding:1px 2px 2px 1px;scrollbar-width:thin}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld.w,.chk.w{grid-column:1/-1}\n.fl{font-size:11.5px;color:var(--muted)}\n.seg{display:flex;gap:4px}\n.seg .btn{flex:1;padding:0 4px}\n.tpbox{display:flex;flex-direction:column;gap:5px}\n.sugg{display:flex;flex-wrap:wrap;gap:4px}\n.chk{display:flex;align-items:center;gap:6px;font-size:12.5px;min-height:28px}\n.chk input{width:16px;height:16px;margin:0;accent-color:var(--accent)}\n.fld.danger{padding-top:6px;border-top:1px dashed var(--line)}\n.fld.danger .btn{align-self:flex-start}\n\n/* size layouts */\n.card[data-size=\"3x3\"]{padding:6px;gap:5px}\n.card[data-size=\"3x3\"] .ttl{display:none}\n.card[data-size=\"3x3\"] .add{padding:0 8px}\n.card[data-size=\"3x3\"] .row{padding:5px 7px}\n.card[data-size=\"3x3\"] .dname{font-size:13px}\n.card[data-size=\"3x3\"] .foot .btn{height:28px}\n\n.card[data-size=\"3x6\"] .top{flex-wrap:wrap}\n.card[data-size=\"3x6\"] .ttl{flex:1 0 100%}\n.card[data-size=\"3x6\"] .row .tp,.card[data-size=\"3x6\"] .row .loc{display:block}\n\n.card[data-size=\"6x3\"] .body,.card[data-size=\"6x6\"] .body{flex-direction:row}\n.card[data-size=\"6x3\"] .chips,.card[data-size=\"6x6\"] .chips{flex-direction:column;overflow-x:hidden;overflow-y:auto;width:96px;padding:0 2px 0 0}\n.card[data-size=\"6x3\"] .chip,.card[data-size=\"6x6\"] .chip{width:100%;max-width:none;border-radius:8px;height:26px}\n.card[data-size=\"6x3\"] .chip .nm,.card[data-size=\"6x6\"] .chip .nm{flex:1}\n.card[data-size=\"6x3\"] .ver,.card[data-size=\"6x3\"] .row{padding:5px 8px}\n.card[data-size=\"6x3\"] .top .search,.card[data-size=\"6x6\"] .top .search{height:28px}\n\n.card[data-size=\"6x6\"]{padding:10px;gap:8px}\n.card[data-size=\"6x6\"] .chips{width:112px}\n.card[data-size=\"6x6\"] .row{padding:7px 10px;gap:2px}\n.card[data-size=\"6x6\"] .row .tp,.card[data-size=\"6x6\"] .row .loc,.card[data-size=\"6x6\"] .row .chg{display:block}\n.card[data-size=\"6x6\"] .empty .long{display:block}\n.card[data-size=\"6x6\"] .ttl{font-size:15px}\n.card[data-size=\"6x6\"] .vers{gap:8px}\n.card[data-size=\"6x6\"] .ver{padding:9px 11px}\n.card[data-size=\"6x3\"] .empty .long{display:block;font-size:11px}\n";
function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat(2).filter(k=>k!==null&&k!==undefined&&k!==false));
  const KINDS=['数据表','图表','文稿'];
  const NONE='__none';
  const small=size==='3x3'||size==='3x6';
  const txt=s=>String(s==null?'':s).trim();
  const one=s=>txt(s).replace(/\s+/g,' ');
  const lc=s=>String(s==null?'':s).toLowerCase();
  const filesOf=s=>(s&&Array.isArray(s.files))?s.files:[];
  const files=filesOf(state).map(f=>Object.assign({},f,{versions:Array.isArray(f.versions)?f.versions:[]}));
  const byNew=f=>f.versions.map((v,i)=>({v,i})).sort((a,b)=>a.v.date===b.v.date?b.i-a.i:(a.v.date<b.v.date?1:-1)).map(x=>x.v);
  const adoptedOf=f=>f.versions.find(v=>v.id===f.adopted)||null;
  const shownOf=f=>adoptedOf(f)||byNew(f)[0]||null;
  const lastDate=f=>{const v=byNew(f)[0];return v?v.date:'';};
  const topicOf=f=>one(f.topic);
  const find=id=>files.find(f=>f.id===id)||null;
  const clear=n=>{while(n.firstChild)n.removeChild(n.firstChild);};
  const run=p=>Promise.resolve(p).catch(e=>{ui.msg='保存失败，请重试'+(e&&e.message?'（'+e.message+'）':'');redraw();});
  const go=(page,extra)=>{ui.page=page;ui.msg='';ui.err='';ui.confirm='';Object.assign(ui,extra||{});redraw();};
  const upd=(id,fn)=>update(s=>Object.assign({},s,{files:filesOf(s).map(f=>f.id===id?fn(Object.assign({},f,{versions:Array.isArray(f.versions)?f.versions:[]})):f)}));
  const autoLabel=vs=>{let n=vs.length+1;while(vs.some(v=>lc(v.label)==='v'+n))n++;return 'v'+n;};
  let listEl=null,chipsEl=null,cntEl=null;

  function topicInfo(){
    const m=new Map();let none=0;
    files.forEach(f=>{const t=topicOf(f);if(!t)none++;else m.set(t,(m.get(t)||0)+1);});
    const list=Array.from(m.keys()).sort((a,b)=>a.localeCompare(b,'zh')).map(k=>({key:k,name:k,n:m.get(k)}));
    return {list,none};
  }
  function matchF(f,q){
    if(lc([f.name,f.kind,f.topic].join('\n')).includes(q))return {ok:true};
    for(const v of byNew(f)){
      for(const k of ['label','location','change']){
        if(lc(v[k]).includes(q))return {ok:true,v,k};
      }
    }
    return {ok:false};
  }
  function visible(){
    const q=lc(one(ui.q));const t=ui.topic;const out=[];
    files.forEach(f=>{
      const tp=topicOf(f);
      if(t===NONE?tp!=='':(t&&tp!==t))return;
      const m=q?matchF(f,q):{ok:true};
      if(m.ok)out.push({f,m});
    });
    out.sort((a,b)=>{
      const x=lastDate(a.f),y=lastDate(b.f);
      return x<y?1:x>y?-1:a.f.name.localeCompare(b.f.name,'zh');
    });
    return out;
  }
  function openForm(mode,fid,vid){
    const f=fid?find(fid):null;let d;
    if(mode==='newFile'){
      d={name:'',kind:KINDS[0],topic:(ui.topic&&ui.topic!==NONE)?ui.topic:'',label:'',date:day(),location:'',change:'',adopt:true};
    }else if(mode==='editFile'){
      d={name:f.name,kind:f.kind,topic:f.topic||''};
    }else if(mode==='newVer'){
      const s=shownOf(f);
      d={label:'',date:day(),location:s?s.location:'',change:'',adopt:false};
    }else{
      const v=f.versions.find(x=>x.id===vid);
      d={label:v.label,date:v.date,location:v.location,change:v.change||'',adopt:f.adopted===v.id};
    }
    go('form',{form:{mode,fid:fid||'',vid:vid||''},draft:d});
  }


  function rowFor(f,m){
    const a=adoptedOf(f),v=shownOf(f);
    const hit=m.v?h('div',{class:'hit'},'命中 '+(m.v.label||'')+'：'+txt(m.v[m.k])):null;
    return h('button',{class:'row',type:'button',onclick:()=>{ui.scroll=listEl?listEl.scrollTop:0;go('detail',{fid:f.id});}},
      h('div',{class:'r1'},h('span',{class:'nm'},f.name),h('span',{class:'tag'},f.kind)),
      h('div',{class:'r2'},
        h('span',{class:'ad'+(a?'':' none')},v?((a?'✓ 采用 ':'未标采用 · 最新 ')+v.label):'暂无版本'),
        h('span',{class:'dt'},v?v.date:'')),
      h('div',{class:'tp'},(topicOf(f)||'未归类')+' · 共 '+f.versions.length+' 版'),
      v&&v.location?h('div',{class:'loc'},v.location):null,
      v&&v.change?h('div',{class:'chg'},v.change):null,
      hit);
  }
  function fill(){
    const info=topicInfo();
    if(ui.topic&&ui.topic!==NONE&&!info.list.some(x=>x.key===ui.topic))ui.topic='';
    if(ui.topic===NONE&&!info.none)ui.topic='';
    const cur=ui.topic||'';
    clear(chipsEl);
    chipsEl.className='chips'+(info.list.length?'':' off');
    const chip=(key,name,n)=>h('button',{class:'chip'+(cur===key?' on':''),type:'button','aria-pressed':String(cur===key),onclick:()=>{ui.topic=key;fill();}},
      h('span',{class:'nm'},name),h('span',{class:'n'},String(n)));
    chipsEl.appendChild(chip('','全部',files.length));
    info.list.forEach(x=>chipsEl.appendChild(chip(x.key,x.name,x.n)));
    if(info.none&&info.list.length)chipsEl.appendChild(chip(NONE,'未归类',info.none));
    clear(listEl);
    const vis=visible();
    cntEl.textContent=' · '+(vis.length===files.length?files.length+' 份':vis.length+' / '+files.length+' 份');
    if(!files.length){
      listEl.appendChild(h('div',{class:'empty'},
        h('div',{class:'et'},'还没有登记研究材料'),
        h('div',{class:'long'},'把数据表、图表和文稿的名称、存放位置、各版本的日期和改动记在这里，可标出当前采用的版本，也能按研究主题查找。'),
        h('button',{class:'btn pri',type:'button',onclick:()=>openForm('newFile')},'+ 登记第一份')));
    }else if(!vis.length){
      listEl.appendChild(h('div',{class:'empty'},
        h('div',{class:'et'},'没有匹配的材料'),
        h('button',{class:'btn',type:'button',onclick:()=>{ui.q='';ui.topic='';redraw();}},'清除搜索与主题')));
    }else{
      vis.forEach(x=>listEl.appendChild(rowFor(x.f,x.m)));
    }
  }
  function renderListPage(){
    chipsEl=h('div',{class:'chips'});listEl=h('div',{class:'list'});cntEl=h('span',{class:'cnt'});
    const input=h('input',{class:'inp search',type:'search',value:ui.q||'',placeholder:small?'搜索':'搜索名称、主题、位置、改动','aria-label':'搜索研究材料',
      oninput:e=>{ui.q=e.target.value;fill();}});
    root.appendChild(h('div',{class:'top'},
      h('div',{class:'ttl'},'研究材料目录',cntEl),
      input,
      h('button',{class:'btn pri add',type:'button',onclick:()=>openForm('newFile')},'+ 登记')));
    if(ui.msg)root.appendChild(h('div',{class:'err',role:'alert'},'⚠ '+ui.msg));
    root.appendChild(h('div',{class:'body'},chipsEl,listEl));
    fill();
    if(ui.scroll){listEl.scrollTop=ui.scroll;ui.scroll=0;}
  }


  function verCard(f,v){
    const cur=f.adopted===v.id;
    const askDel=ui.confirm==='v:'+v.id;
    const acts=askDel
      ?h('div',{class:'acts'},
          h('span',{class:'ask'},'确定删除 '+v.label+'？'),
          h('button',{class:'btn sm',type:'button',onclick:()=>{ui.confirm='';redraw();}},'取消'),
          h('button',{class:'btn sm pri',type:'button',onclick:()=>{
            ui.confirm='';
            run(upd(f.id,x=>Object.assign({},x,{versions:x.versions.filter(y=>y.id!==v.id),adopted:x.adopted===v.id?'':x.adopted})));
          }},'确认删除'))
      :h('div',{class:'acts'},
          h('button',{class:'btn sm'+(cur?'':' pri'),type:'button',onclick:()=>{
            run(upd(f.id,x=>Object.assign({},x,{adopted:x.adopted===v.id?'':v.id})));
          }},cur?'取消采用':'设为当前采用'),
          h('button',{class:'btn sm',type:'button',onclick:()=>openForm('editVer',f.id,v.id)},'编辑'),
          f.versions.length>1?h('button',{class:'btn sm',type:'button',onclick:()=>{ui.confirm='v:'+v.id;redraw();}},'删除'):null);
    return h('div',{class:'ver'+(cur?' cur':'')},
      h('div',{class:'vh'},
        h('b',{class:'vl'},v.label),
        h('span',{class:'vd'},v.date),
        cur?h('span',{class:'badge'},'✓ 当前采用'):null),
      h('div',{class:'kv'},h('span',{class:'k'},'位置'),h('span',{class:'v mono'},v.location)),
      h('div',{class:'kv'},h('span',{class:'k'},'改动'),h('span',{class:'v'},v.change||'（未填写）')),
      acts);
  }
  function renderDetail(f){
    const vs=byNew(f);
    root.appendChild(h('div',{class:'dtop'},
      h('button',{class:'btn',type:'button',onclick:()=>go('list')},'‹ 返回'),
      h('div',{class:'dname'},f.name),
      h('button',{class:'btn',type:'button',onclick:()=>openForm('editFile',f.id)},'编辑')));
    if(ui.msg)root.appendChild(h('div',{class:'err',role:'alert'},'⚠ '+ui.msg));
    const a=adoptedOf(f);
    root.appendChild(h('div',{class:'vers'},
      h('div',{class:'dmeta'},
        h('span',{class:'tag'},f.kind),
        h('span',{class:'tag tl'},topicOf(f)?'主题：'+topicOf(f):'未归类主题'),
        h('span',{class:'tag'},'共 '+vs.length+' 版'),
        a?null:h('span',{class:'tag warn'},'⚠ 还没标当前采用版本')),
      vs.map(v=>verCard(f,v))));
    root.appendChild(h('div',{class:'foot'},
      h('button',{class:'btn pri',type:'button',onclick:()=>openForm('newVer',f.id)},'+ 新增版本')));
  }


  function renderForm(){
    const m=ui.form,d=ui.draft,mode=m.mode;
    const f=m.fid?find(m.fid):null;
    const isF=mode==='newFile'||mode==='editFile';
    const isV=mode!=='editFile';
    const titles={newFile:'登记新材料',editFile:'编辑材料信息',newVer:'新增版本 · '+(f?f.name:''),editVer:'编辑版本 · '+(f?f.name:'')};
    const set=k=>e=>{d[k]=e.target.value;};
    const fld=(label,req,node,wide)=>h('div',{class:'fld'+(wide?' w':'')},h('span',{class:'fl'},label+(req?' *':'')),node);
    const items=[];
    if(isF){
      items.push(fld('名称',true,h('input',{class:'inp',value:d.name,placeholder:'如：问卷A清洗后数据','aria-label':'名称',oninput:set('name')}),true));
      items.push(fld('类型',false,h('div',{class:'seg'},KINDS.map(k=>h('button',{class:'btn'+(d.kind===k?' on':''),type:'button','aria-pressed':String(d.kind===k),onclick:()=>{d.kind=k;redraw();}},k))),true));
      const sug=topicInfo().list.map(x=>x.key);
      items.push(fld('研究主题',false,h('div',{class:'tpbox'},
        h('input',{class:'inp',value:d.topic,placeholder:'如：睡眠与学习成绩（可留空）','aria-label':'研究主题',oninput:set('topic')}),
        sug.length?h('div',{class:'sugg'},sug.map(t=>h('button',{class:'chip sm'+(one(d.topic)===t?' on':''),type:'button',onclick:()=>{d.topic=t;redraw();}},h('span',{class:'nm'},t)))):null),true));
    }
    if(isV){
      items.push(fld('版本号',false,h('input',{class:'inp',value:d.label,placeholder:mode==='newFile'?'不填则记为 v1':'不填则自动编号','aria-label':'版本号',oninput:set('label')}),false));
